#define CHECK(x) do{if(!(x)){std::cerr<<__LINE__<<": " #x "\n";return 1;}}while(false)
bool parse_fixture(const std::string& children,xml::Request& r){std::string source="<LSX><Request id='A&amp;lt;' recipient='Ach&amp;X'><QueryAchievements>"+children+"</QueryAchievements></Request></LSX>";const auto result=xml::parse(source,r);source.assign(source.size(),'!');return result==xml::Result::ok;}
ResponseResult render(const ConfigSnapshot& s,const std::string& children,std::string& wire){xml::Request r;if(!parse_fixture(children,r))return ResponseResult::rejected;std::array<char,16384> out{};std::size_t n=99;const auto result=dispatch_response_with_config(r,s,out.data(),out.size(),&n);wire.assign(out.data(),n);return result;}
std::vector<std::string> ids(const std::string& wire){tinyxml2::XMLDocument d;if(d.Parse(wire.data(),wire.size())!=tinyxml2::XML_SUCCESS)return {"!XML"};const auto* r=d.RootElement()->FirstChildElement("Response");if(!r || !r->Attribute("id","A&lt;") || !r->Attribute("sender","Ach&X"))return {"!ENVELOPE"};const auto* sets=r->FirstChildElement("AchievementSets");const auto* set=sets?sets->FirstChildElement("AchievementSet"):nullptr;if(!set)return {"!BODY"};std::vector<std::string> result;for(auto* a=set->FirstChildElement();a;a=a->NextSiblingElement()){if(!a->Attribute("Id"))return {"!ID"};result.emplace_back(a->Attribute("Id"));}return result;}
int main(){
    ConfigStore store;std::string wire;CHECK(render(*store.snapshot(),"<All>true</All>",wire)==ResponseResult::response && ids(wire).empty() && wire.find("GameName=\"Game\" Name=\"\"/>")!=std::string::npos);
    CHECK(store.replace(R"("Config2" {"Game" {"Name" "old" "GameName" "G&"} "Achievements" {"AchievementsSet" "old" "AchievementsSet" "S&amp;" "AchievementNames" {"A&" "Alpha&" "B" "Beta"} "AchievementTotals" {"A&" "-2147483648" "B" "+2147483647"}}})")==ConfigResult::published);const auto held=store.snapshot();
    struct Case{const char* text;bool all;};const Case cases[]={{"",false},{"<All>true</All>",true},{"<All>&#116;rue</All>",true},{"<All><![CDATA[true]]></All>",true},{"<All> true</All>",false},{"<All>true </All>",false},{"<All>TRUE</All>",false},{"<All>1</All>",false},{"<All/>",false},{"<all>true</all>",false},{"<Other><All>true</All></Other>",false},{"<All>false</All><All>true</All>",false},{"<All>true</All><All><Nested/></All>",true},{"<All>true<!--c-->tail</All>",false},{"<All><!--c--></All>",false}};
    for(const auto& c:cases){CHECK(render(*held,c.text,wire)==ResponseResult::response);const std::vector<std::string> expected=c.all?std::vector<std::string>{"A&","B"}:std::vector<std::string>{};CHECK(ids(wire)==expected);}
    CHECK(render(*held,"<All>true</All>",wire)==ResponseResult::response);
    const std::string literal=" <LSX>\n  <Response id=\"A&amp;lt;\" sender=\"Ach&amp;X\">\n    <AchievementSets>\n      <AchievementSet GameName=\"G&amp;\" Name=\"S&amp;amp;\">\n        <Achievement Id=\"A&amp;\" Total=\"-2147483648\" Count=\"0\" Progress=\"0\" GrantDate=\"0000-00-00T00:00:00\" Expiration=\"0000-00-00T00:00:00\" ImageId=\"\" Name=\"Alpha&amp;\" Description=\"\" HowTo=\"\"/>\n        <Achievement Id=\"B\" Total=\"2147483647\" Count=\"0\" Progress=\"0\" GrantDate=\"0000-00-00T00:00:00\" Expiration=\"0000-00-00T00:00:00\" ImageId=\"\" Name=\"Beta\" Description=\"\" HowTo=\"\"/>\n      </AchievementSet>\n    </AchievementSets>\n  </Response>\n </LSX>\n";CHECK(wire==literal);
    xml::Request r;CHECK(parse_fixture("<All>true</All>",r));std::array<char,16384> out;out.fill('#');std::size_t n=99;CHECK(dispatch_response(r,out.data(),out.size(),&n)==ResponseResult::no_response && n==0);AuthCodeSession auth;CHECK(dispatch_response_with_session(r,*held,auth,out.data(),out.size(),&n)==ResponseResult::response && std::string(out.data(),n)==literal && !auth.ready());const auto need=n;
    out.fill('#');CHECK(dispatch_achievement_response(r,*held,out.data(),8,&n)==ResponseResult::rejected && n==0 && out[0]=='#');CHECK(dispatch_achievement_response(r,*held,out.data(),need,&n)==ResponseResult::rejected && n==0 && out[0]=='#');CHECK(dispatch_achievement_response(r,*held,out.data(),need+1,&n)==ResponseResult::response && n==need && out[n]=='\0');CHECK(dispatch_achievement_response(r,*held,nullptr,out.size(),&n)==ResponseResult::rejected && n==0);CHECK(dispatch_achievement_response(r,*held,out.data(),0,&n)==ResponseResult::rejected && n==0);CHECK(dispatch_achievement_response(r,*held,out.data(),out.size(),nullptr)==ResponseResult::rejected);
    const auto id=r.id;r.id={};out.fill('#');CHECK(dispatch_achievement_response(r,*held,out.data(),out.size(),&n)==ResponseResult::rejected && n==0 && out[0]=='#');r.id=id;
    for(unsigned field=0;field<7;++field){ConfigSnapshot bad=*held;auto& a=bad.achievements.back();std::string* v[]={&a.id,&a.name,&a.description,&a.how_to,&a.image_id,&a.grant_date,&a.expiration};*v[field]=std::string(1,'\1');out.fill('#');CHECK(dispatch_achievement_response(r,bad,out.data(),out.size(),&n)==ResponseResult::rejected && n==0 && out[0]=='#');CHECK(render(bad,"",wire)==ResponseResult::response && ids(wire).empty());}
    ConfigSnapshot progressed=*held;progressed.achievements[1].progress=1;progressed.achievements[1].count=2;CHECK(render(progressed,"",wire)==ResponseResult::response && ids(wire)==std::vector<std::string>{"B"} && wire.find("Count=\"2\" Progress=\"1\"")!=std::string::npos);
    for(const auto* text:{"<All><Nested/></All>","bad<All>true</All>"}){CHECK(parse_fixture(text,r));out.fill('#');CHECK(dispatch_achievement_response(r,*held,out.data(),out.size(),&n)==ResponseResult::rejected && n==0 && out[0]=='#');ConfigSnapshot empty;CHECK(dispatch_achievement_response(r,empty,out.data(),out.size(),&n)==ResponseResult::rejected && n==0);}
    CHECK(store.replace(R"("Config2" {"Game" {"Name" ""} "Achievements" {"AchievementsSet" ""}})")==ConfigResult::published);CHECK(render(*store.snapshot(),"",wire)==ResponseResult::response && wire.find("GameName=\"\" Name=\"\"/>")!=std::string::npos);CHECK(render(*held,"<All>true</All>",wire)==ResponseResult::response && wire==literal);
    ConfigSnapshot many=*held;many.achievements.clear();for(unsigned i=0;i<600;++i){auto a=held->achievements[0];a.id=std::to_string(i);many.achievements.push_back(std::move(a));}CHECK(parse_fixture("<All>true</All>",r));std::string large(500000,'#');CHECK(dispatch_achievement_response(r,many,large.data(),large.size(),&n)==ResponseResult::response && n>16384 && ids(std::string(large.data(),n)).size()==600);out.fill('#');CHECK(dispatch_achievement_response(r,many,out.data(),out.size(),&n)==ResponseResult::rejected && n==0 && out[0]=='#');
    const char* yes=R"("Config2" {"Game" {"Name" "Alpha"} "Achievements" {"AchievementsSet" "SA" "AchievementNames" {"A" "alpha"}}})";const char* no=R"("Config2" {"Game" {"Name" "Beta"} "Achievements" {"AchievementsSet" "SB" "AchievementNames" {"B" "beta"}}})";CHECK(store.replace(yes)==ConfigResult::published);std::atomic<bool> bad=false;std::thread writer([&]{for(unsigned i=0;i<200;++i)if(store.replace(i%2?yes:no)!=ConfigResult::published)bad=true;});
    for(unsigned i=0;i<200;++i){const auto s=store.snapshot();std::string w;const bool a=s->achievements[0].id=="A";if(render(*s,"<All>true</All>",w)!=ResponseResult::response || w.find(a?"GameName=\"Alpha\" Name=\"SA\"":"GameName=\"Beta\" Name=\"SB\"")==std::string::npos || ids(w)!=std::vector<std::string>{a?"A":"B"})bad=true;}
    writer.join();CHECK(!bad);std::cout<<"QUERY_ACHIEVEMENTS_ALL_EXACT_WIRE_MEASURE_SNAPSHOT_PASS\n";
}
